update public.twilio_response_rules as rules
set response_text = revised.response_text, updated_at = now()
from (values
  ('attendance_payment_pending', '🎉 *باقي خطوة واحدة لتأكيد مقعدك!*\n\nرقم مشاركتك: *{participant_number}*\nالسعر المستحق الآن: *{price} ريال* ({price_label})\n\n💡 السعر المبكر هو *{early_price} ريال*، وبعد انتهاء الفترة المبكرة يصبح السعر *{late_price} ريال*.\n\n💳 *بيانات التحويل*\n• STC Pay: {stc_pay}\n• {bank_name}\n• IBAN: {iban}\n\n*يُحجز مقعدك فقط بعد الدفع وإرسال الإيصال.* ادفع الآن لتأكيد مقعدك قبل اكتمال المقاعد، ثم أرسل الإيصال هنا كصورة واضحة أو PDF.'),
  ('attendance_paid', '🎉 *مقعدك مؤكد!*\n\nتم اعتماد دفعتك وتأكيد حضورك بنجاح. ستجد أدناه المكان والوقت ورابط شرح التجربة قبل الحضور.'),
  ('attendance_waived', '🎉 *مقعدك مؤكد!*\n\nتم تأكيد حضورك مع إعفاء الدفع. ستجد أدناه المكان والوقت ورابط شرح التجربة قبل الحضور.'),
  ('attendance_confirmation_pending', '🎉 *سجّلنا حضورك!*\n\nاختيارك الحالي: *سأحضر*. إذا تغيّر قرارك لاحقاً، أرسل كلمة *اعتذار* وسنحدّث حالتك.'),
  ('attendance_denial_pending', '🙏 *سجّلنا اعتذارك عن الحضور*\n\nإذا تغيّر قرارك لاحقاً، أرسل كلمة *تأكيد* وسنحدّث حالتك.'),
  ('attendance_denied', '🙏 *تم تسجيل اعتذارك*\n\nشكراً لأنك بلّغتنا.\n\n🔄 حالة التسجيل التلقائي لديك: *{auto_signup_status}*\n{auto_signup_action}\n\nنتمنى نشوفك في فعالية قادمة!'),
  ('age_expand_2', '🎯 *وسّعنا نطاق العمر لك*\n\nأضفنا *سنتين* كنطاق إضافي لهذه الفعالية فقط. تفضيل العمر الأساسي المحفوظ في ملفك *لم يتغير*، وينتهي هذا التوسيع تلقائياً بعد الفعالية.'),
  ('age_expand_5', '🎯 *وسّعنا نطاق العمر لك*\n\nأضفنا *5 سنوات* كنطاق إضافي لهذه الفعالية فقط. تفضيل العمر الأساسي المحفوظ في ملفك *لم يتغير*، وينتهي هذا التوسيع تلقائياً بعد الفعالية.'),
  ('discount_interested', '🎁 *العرض جاهز لك*\n\nأكمل الدفع الآن باستخدام البيانات أدناه، ثم أرسل الإيصال هنا كصورة أو PDF. لا يُثبت الحجز إلا بعد استلام الإيصال.'),
  ('auto_signup_enabled', '🔔 *تم تفعيل التسجيل التلقائي*\n\nسنضيفك تلقائياً إلى قائمة المهتمين بأي فعالية قادمة مناسبة، ثم نراسلك لتأكيد حضورك. لن يتم طلب دفع دون اختيارك.\n\nلإيقاف التسجيل التلقائي أرسل: *إيقاف*'),
  ('auto_signup_already', '🔔 *التسجيل التلقائي مفعّل بالفعل*\n\nستتم إضافتك تلقائياً إلى قائمة المهتمين بأي فعالية قادمة مناسبة. لإيقافه أرسل: *إيقاف*'),
  ('auto_signup_stopped', '🛑 *تم إيقاف التسجيل التلقائي*\n\nلن نضيفك تلقائياً إلى الفعاليات القادمة. لإعادة تفعيله أرسل: *تفعيل*'),
  ('auto_signup_already_stopped', '👌 *التسجيل التلقائي متوقف بالفعل*\n\nلن تتم إضافتك تلقائياً إلى الفعاليات القادمة. لتفعيله أرسل: *تفعيل*'),
  ('unknown_message', 'أهلاً بك 👋\n\nتقدر ترد بإحدى الكلمات التالية:\n• *تأكيد* — لتسجيل حضورك\n• *اعتذار* — إذا لن تتمكن من الحضور\n• *تفعيل* — لتفعيل التسجيل التلقائي للفعاليات القادمة\n• *إيقاف* — لإيقاف التسجيل التلقائي\n\nولرفع إيصال، أرسله هنا كصورة أو PDF.\n\nتحتاج مساعدة؟ تواصل مع المنظم على *0560899666*.'),
  ('receipt_unsupported', '📎 *لم نتمكن من قراءة المرفق كإيصال*\n\nأعد إرساله كصورة واضحة أو ملف PDF. إذا احتجت مساعدة تواصل مع المنظم على *0560899666*.'),
  ('receipt_rejected_reason', '⚠️ *يحتاج الإيصال إلى إعادة إرسال*\n\nالسبب: *{reason}*\n\nأرسل إيصالاً واضحاً وصحيحاً هنا كصورة أو PDF. إذا احتجت توضيحاً تواصل مع المنظم على *0560899666*.'),
  ('receipt_rejected_generic', '⚠️ *يحتاج الإيصال إلى إعادة إرسال*\n\nتأكد أن الصورة واضحة وتظهر تفاصيل التحويل، ثم أرسلها هنا كصورة أو PDF. إذا احتجت توضيحاً تواصل مع المنظم على *0560899666*.')
) as revised(action_key, response_text)
where rules.action_key = revised.action_key;
